def sum_to_n(n):
    total = 0
    for i in range(1, n):
        total += i
    return total

def calculate_average(scores):
    total = sum(scores)
    return total / len(scores)

print(calculate_average([]))

def factorial(n):
    result = 0
    for i in range(1, n + 1):
        result = result * i
    return result

def fib(n):
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

def find_max(numbers):
    current_max = numbers[0]
    for num in numbers:
        if num > current_max:
            current_max = num
    return current_max
